function toast(t='Saved ✓'){let e=document.querySelector('.wr21-toast');if(!e){e=document.createElement('div');e.className='wr21-toast';document.body.appendChild(e)}e.textContent=t;e.classList.add('show');clearTimeout(e._t);e._t=setTimeout(()=>e.classList.remove('show'),1600)}
async function uid(){const{data}=await supabase.auth.getUser();return data?.user?.id||null}
const roots=()=>S.cargo.filter(x=>!x.parent_id),children=id=>S.cargo.filter(x=>x.parent_id===id),ent=id=>S.entities.find(x=>x.id===id),party=r=>S.parties.find(x=>String(x.role||'').toLowerCase()===r);
const packageTypes=()=>{const custom=(S.options||[]).filter(x=>x.option_group==='PACKAGE_TYPE'&&x.active).map(x=>[x.code,x.uom||x.code]);return [...new Map([...TYPES,...custom].map(x=>[x[0],x])).values()]};
const steps=()=>[...(S.workflow?.steps||FALLBACK)].filter(x=>x.enabled!==false).sort((a,b)=>(a.order||0)-(b.order||0));
const skipped=k=>S.events.some(e=>e.event_type==='STEP_SKIPPED'&&e.event_data?.step_key===k);
const customerName=()=>ent(S.job?.customer_id)?.name||'Unidentified customer';
function done(s){const v=S.visit||{},r=roots();switch(s.key){case'check_in':return!!v.time_in;case'verify_driver':return!!v.driver_id_verified;case'start_unload':return!!v.operation_started_at;case'finish_unload':return!!v.operation_completed_at;case'release_driver':return!!v.time_out;case'parties':return(!!S.job?.customer_id&&!!party('shipper')&&!!party('consignee'))||skipped('parties');case'receive_cargo':return r.length>0&&r.every(x=>x.processing_status==='processed');case'documents':return S.docs.length>0||skipped('documents');case'compliance':return S.controls.length===0||S.controls.every(x=>x.verified||['complete','cleared','released'].includes(String(x.status||'').toLowerCase()))||skipped('compliance');case'putaway':return(r.length>0&&r.every(x=>x.current_location_id||x.warehouse_location_id))||skipped('putaway');case'complete':return!!S.wr.completed_at;case'notify_customer':return S.events.some(e=>e.event_type==='CUSTOMER_NOTIFIED')||skipped('notify_customer');default:return S.events.some(e=>e.event_type==='STEP_COMPLETED'&&e.event_data?.step_key===s.key)||skipped(s.key)}}
const autoCurrent=()=>steps().find(x=>!done(x))||steps().at(-1);
const current=()=>steps().find(x=>x.key===manualStep)||autoCurrent();
function missing(){const m=[];if(!S.job?.customer_id)m.push('Customer');if(!party('shipper'))m.push('Shipper');if(!party('consignee'))m.push('Consignee');if(!roots().filter(x=>x.processing_status!=='pending'||!x.metadata?.editor_draft).length)m.push('Cargo');if(S.visit?.time_in&&!S.visit?.time_out)m.push('Driver on site');if(roots().length&&roots().some(x=>!(x.current_location_id||x.warehouse_location_id)))m.push('Put-away');if(S.flags.length)m.push(`${S.flags.length} exception${S.flags.length===1?'':'s'}`);if(S.controls.some(x=>!x.verified&&!['complete','cleared','released'].includes(String(x.status||'').toLowerCase())))m.push('Compliance');return m}
function summary(){const r=roots().filter(x=>!x.metadata?.editor_draft),processed=r.filter(x=>x.processing_status==='processed').reduce((a,x)=>a+Number(x.quantity||0),0),putaway=r.filter(x=>x.current_location_id||x.warehouse_location_id).reduce((a,x)=>a+Number(x.quantity||0),0);return{expected:S.visit?.unload_expected_qty,unloaded:S.visit?.unload_actual_qty,processed,putaway,exceptions:S.flags.length,missing:missing().length}}
function completion(){const a=steps(),n=a.filter(done).length;return{pct:a.length?Math.round(n/a.length*100):0}}
async function addEvent(type,data={}){await supabase.from('workflow_events').insert({organization_id:S.wr.organization_id,job_id:S.wr.job_id,warehouse_receipt_id:wrId,event_type:type,event_data:data,actor_id:await uid()})}

async function load(id){const{data:wr,error}=await supabase.from('warehouse_receipts').select('*').eq('id',id).single();if(error)throw error;const q=[supabase.from('jobs').select('*').eq('id',wr.job_id).maybeSingle(),supabase.from('warehouse_visits').select('*').eq('warehouse_receipt_id',id).eq('direction','inbound').order('created_at',{ascending:false}).limit(1),supabase.from('cargo_units').select('*').eq('job_id',wr.job_id).order('created_at'),supabase.from('warehouse_receipt_parties').select('*').eq('warehouse_receipt_id',id),supabase.from('entities').select('*').eq('organization_id',wr.organization_id).order('name').limit(2500),supabase.from('documents').select('*').eq('warehouse_receipt_id',id).eq('is_current',true).order('created_at',{ascending:false}),supabase.from('operational_flags').select('*').eq('warehouse_receipt_id',id).eq('active',true).order('created_at',{ascending:false}),supabase.from('receiving_controls').select('*').eq('warehouse_receipt_id',id).order('created_at',{ascending:false}),supabase.from('workflow_definitions').select('*').eq('organization_id',wr.organization_id).eq('transaction_type','WAREHOUSE_RECEIPT').eq('is_active',true).order('version',{ascending:false}).limit(1),supabase.from('workflow_events').select('*').eq('warehouse_receipt_id',id).order('created_at'),supabase.from('warehouse_locations').select('*').eq('organization_id',wr.organization_id).eq('active',true).order('code'),supabase.from('organization_unit_profiles').select('*').eq('organization_id',wr.organization_id).eq('is_default',true).maybeSingle(),supabase.from('organization_reference_options').select('*').eq('organization_id',wr.organization_id).eq('active',true).order('option_group').order('sort_order'),supabase.from('inventory_items').select('id,owner_entity_id,part_number,sku,description,base_uom,lot_tracking,serial_tracking,metadata').eq('organization_id',wr.organization_id).limit(2500)];const [job,visit,cargo,parties,entities,docs,flags,controls,wf,events,locs,units,opts,items]=await Promise.all(q);const ids=(entities.data||[]).map(x=>x.id);let addresses=[],contacts=[];if(ids.length){const[a,c]=await Promise.all([supabase.from('entity_addresses').select('*').in('entity_id',ids).eq('active',true),supabase.from('entity_contacts').select('*').in('entity_id',ids).eq('active',true)]);addresses=a.data||[];contacts=c.data||[]}S={wr,job:job.data||{},visit:visit.data?.[0]||null,cargo:cargo.data||[],parties:parties.data||[],entities:entities.data||[],docs:docs.data||[],flags:flags.data||[],controls:controls.data||[],workflow:wf.data?.[0]||null,events:events.data||[],locations:locs.data||[],units:units.data||{weight_unit:'LB',dimension_unit:'IN',volume_unit:'CBM',default_quantity_uom:'PCS'},options:opts.data||[],items:items.data||[],addresses,contacts};return S}
async function refresh(){await load(wrId)}

function timeline(){const v=S.visit||{};return `<div class="wr21-timeline">${[['Checked in',v.time_in],['ID verified',v.driver_id_verified_at],['Unload started',v.operation_started_at],['Unload finished',v.operation_completed_at],['Released',v.time_out]].map(([l,t])=>`<div class="wr21-event ${t?'done':''}"><small>${l}</small><b>${t?'✓ '+tm(t):'Pending'}</b></div>`).join('')}</div>`}
function commandbar(){return `<div class="wr21-command"><button data-out="pdf">${docIcon}<span>WR PDF</span></button><button data-out="4x6"><span>4×6</span></button><button data-out="2x1"><span>2×1</span></button><span class="wr21-divider"></span><button data-doc-scan>${scanIcon}<span>Scan document</span></button><button data-doc-upload>${docIcon}<span>Upload</span></button><button data-share>${mailIcon}<span>Share WR</span></button></div>`}
function reconciliation(){const s=summary();if(!s.unloaded||s.processed<=s.unloaded)return'';return `<div class="wr21-reconcile"><span>Reconciliation needed · ${s.processed} processed vs ${s.unloaded} unloaded (+${s.processed-s.unloaded}).</span><button data-record-overage>Record overage</button></div>`}
function head(){const s=summary(),c=completion();return `<header class="wr21-head"><div class="wr21-headrow"><div><div class="wr21-k">Warehouse receipt</div><div class="wr19-num wr21-num">${esc(S.wr.receipt_number)}</div><div class="wr21-sub">${esc(customerName())} · Created ${fmt(S.wr.created_at)}${S.wr.received_at?` · Received ${fmt(S.wr.received_at)}`:''}</div></div><span class="wr21-status">${esc(S.wr.status)}</span></div><div class="wr21-mode"><button data-mode="guided" class="${mode==='guided'?'active':''}">Guided</button><button data-mode="record" class="${mode==='record'?'active':''}">Record</button></div>${commandbar()}<div class="wr21-summary"><div class="wr21-stat"><small>Expected</small><b>${s.expected??'—'} ${S.visit?.unload_uom||''}</b></div><div class="wr21-stat"><small>Unloaded</small><b>${s.unloaded??'—'} ${S.visit?.unload_uom||''}</b></div><div class="wr21-stat"><small>Processed</small><b>${s.processed}</b></div><div class="wr21-stat"><small>Put away</small><b>${s.putaway}</b></div><div class="wr21-stat"><small>Exceptions</small><b>${s.exceptions}</b></div><div class="wr21-stat"><small>Missing</small><b>${s.missing}</b></div></div><div class="wr21-meter"><span style="width:${c.pct}%"></span></div>${reconciliation()}</header>`}
function progress(){const c=current();return `<div class="wr21-progress">${steps().map(x=>`<button data-step="${esc(x.key)}" class="${done(x)?'done':''} ${x.key===c?.key?'now':''}">${done(x)?'✓ ':''}${esc(x.label)}${x.required===false?' · optional':''}</button>`).join('')}</div>`}
function guideCopy(k){return({check_in:'Capture only what establishes the dock visit. Everything else can be added later.',verify_driver:'Capture the driver ID, then record the verification statement.',start_unload:'Start the physical unload when custody transfer begins.',finish_unload:'Record the physical tally. Detailed receiving can continue after the truck leaves.',release_driver:'Capture the driver signature and close the dock visit.',parties:'Confirm Customer, Shipper and Consignee. If unknown, mark identity pending and keep moving.',receive_cargo:'Build the physical cargo hierarchy. NODARA autosaves the working cargo draft.',documents:'Capture and organize receiving documents by type and cargo.',compliance:'Review DG, in-bond / 7512 and FTZ controls only when applicable.',putaway:'Assign or scan locations. You may skip for now and return later.',complete:'Review unresolved requirements and close the Warehouse Receipt.',notify_customer:'Share the WR or record that the customer was notified.'}[k]||'Complete this step.')}
function guided(){const s=current(),i=steps().findIndex(x=>x.key===s.key);return `<section class="wr21-guide wr21-panel">${progress()}<div class="wr21-now">RIGHT NOW · ${i+1} OF ${steps().length}</div><h1 class="wr21-title">${esc(s.label)}</h1><div class="wr21-copy">${esc(s.description||guideCopy(s.key))}</div>${timeline()}${guidedTask(s)}</section>`}
function smartField(id,label,value='',role=''){return `<label class="wr21-field" data-smart-wrap><span>${esc(label)}</span><input id="${id}" data-smart="${esc(role)}" value="${esc(value)}" autocomplete="off" placeholder="Search, type once, or create new"><div class="wr21-smartmenu" hidden></div><div class="wr21-preview" data-preview hidden></div></label>`}
function partyCard(role){const p=role==='customer'?ent(S.job?.customer_id):ent(party(role)?.entity_id),name=role==='customer'?customerName():(party(role)?.display_name||p?.name||'Not selected');if(!p)return `<div class="wr21-party"><small>${esc(role)}</small><h4>${esc(name)}</h4><div class="addr">${name==='Not selected'||name==='Unidentified customer'?'Pending':'Typed for this WR only'}</div></div>`;const a=S.addresses.find(x=>x.entity_id===p.id&&x.is_primary)||S.addresses.find(x=>x.entity_id===p.id),c=S.contacts.find(x=>x.entity_id===p.id&&x.is_primary)||S.contacts.find(x=>x.entity_id===p.id);return `<div class="wr21-party"><small>${esc(role)}</small><h4>${esc(p.name)}</h4><div class="addr">${esc([a?.line1,a?.line2,[a?.city,a?.state_region,a?.postal_code].filter(Boolean).join(' '),a?.country_code].filter(Boolean).join(' · ')||'No saved address')}</div><div class="contact">${esc([c?.name,c?.phone,c?.email].filter(Boolean).join(' · ')||'No primary contact')}</div></div>`}
function guidedTask(s){const v=S.visit||{};switch(s.key){case'check_in':return `<div class="wr21-task"><h3>Who just arrived?</h3><div class="wr21-fields">${smartField('g-carrier','Carrier',v.carrier_name_snapshot||'','carrier')}<label class="wr21-field"><span>Driver</span><input id="g-driver" value="${esc(v.driver_name||'')}" placeholder="Driver name"></label><label class="wr21-field"><span>Reference</span><input id="g-ref" value="${esc(v.bol_number||v.pro_number||v.tracking_number||'')}" placeholder="BOL / PRO / tracking"></label><label class="wr21-field"><span>Door</span><input id="g-door" value="${esc(v.door||'')}" placeholder="Optional"></label></div><div class="wr21-actions"><button class="primary" data-g-checkin>Check in</button><button class="wr21-iconbtn" data-scan-ref>${scanIcon} Scan reference</button></div></div>`;case'verify_driver':return `<div class="wr21-task"><h3>Verify identity</h3><p>The ID image is attached directly to this WR / dock visit.</p><div class="wr21-actions"><button class="wr21-iconbtn" data-driver-id>${scanIcon} Scan / capture ID</button></div><label style="display:flex;gap:9px;align-items:flex-start;margin-top:16px;line-height:1.45"><input id="g-verify" type="checkbox" style="width:20px;height:20px;flex:none"> <span>I verified a government-issued photo ID and confirmed it matches the driver presenting the freight.</span></label><div class="wr21-actions"><button class="primary" data-g-verify>Confirm verification</button></div></div>`;case'start_unload':return `<div class="wr21-task"><h3>Ready to unload</h3><div class="wr21-actions"><button class="primary" data-g-start>Start unloading</button></div></div>`;case'finish_unload':return `<div class="wr21-task"><h3>Unload & tally</h3><div class="wr21-fields"><label class="wr21-field"><span>Expected</span><input id="g-exp" type="number" value="${esc(v.unload_expected_qty??'')}"></label><label class="wr21-field"><span>Actual unloaded</span><input id="g-act" type="number" value="${esc(v.unload_actual_qty??'')}"></label><label class="wr21-field"><span>UOM</span><input id="g-uom" value="${esc(v.unload_uom||'PLT')}"></label></div><div class="wr21-actions"><button class="primary" data-g-finish>Finish unloading</button></div></div>`;case'release_driver':return `<div class="wr21-task"><h3>Release driver</h3><p>Capture signature, stamp time-out and release the truck. Warehouse processing continues independently.</p><div class="wr21-actions"><button class="primary" data-g-release>Sign & release driver</button></div></div>`;case'parties':return `<div class="wr21-task"><h3>Parties</h3><div class="wr21-fields">${smartField('g-customer','Customer',customerName()==='Unidentified customer'?'':customerName(),'customer')}${smartField('g-shipper','Shipper',party('shipper')?.display_name||'','shipper')}${smartField('g-consignee','Consignee',party('consignee')?.display_name||'','consignee')}</div><div class="wr21-actions"><button class="primary" data-g-parties>Save & continue</button><button class="quiet" data-skip-parties>Continue · identity pending →</button></div></div>`;case'receive_cargo':return `<div class="wr21-task">${cargoView(true)}</div>`;case'documents':return `<div class="wr21-task">${documentsView()}${s.required===false?'<div class="wr21-actions"><button class="quiet" data-skip="documents">Skip optional step →</button></div>':''}</div>`;case'compliance':return `<div class="wr21-task">${complianceView()}${s.required===false?'<div class="wr21-actions"><button class="quiet" data-skip="compliance">Not applicable / continue →</button></div>':''}</div>`;case'putaway':return `<div class="wr21-task"><h3>Put away</h3>${putawayView()}<div class="wr21-actions"><button class="quiet" data-skip="putaway">Skip for now →</button></div></div>`;case'complete':return `<div class="wr21-task"><h3>Review & complete</h3>${missing().length?`<div class="wr21-card"><b>Still needs attention</b><p>${esc(missing().join(' · '))}</p></div>`:'<div class="wr21-card"><span class="wr21-badge good">Ready</span><p>No blocking items detected.</p></div>'}<div class="wr21-actions"><button class="primary" data-g-complete>Complete WR</button></div></div>`;case'notify_customer':return `<div class="wr21-task"><h3>Notify customer</h3><div class="wr21-actions"><button class="primary" data-share>Share WR</button><button data-g-notify>Mark notified</button><button class="quiet" data-skip="notify_customer">Skip →</button></div></div>`;default:return `<div class="wr21-task"><h3>${esc(s.label)}</h3><div class="wr21-actions"><button class="primary" data-g-generic="${esc(s.key)}">Mark complete</button></div></div>`}}

const TABS=[['overview','Overview'],['parties','Parties'],['arrival','Arrival'],['cargo','Cargo'],['documents','Documents'],['compliance','Compliance'],['exceptions','Exceptions'],['activity','Activity']];
function record(){return `<nav class="wr21-tabs">${TABS.map(([k,l])=>`<button data-tab="${k}" class="${tab===k?'active':''}">${l}</button>`).join('')}</nav><section class="wr21-panel">${recordTab()}</section>`}
function recordTab(){return tab==='overview'?overview():tab==='parties'?partiesView():tab==='arrival'?arrivalView():tab==='cargo'?cargoView(false):tab==='documents'?documentsView():tab==='compliance'?complianceView():tab==='exceptions'?exceptionsView():activityView()}
function overview(){return `<div class="wr21-recordgrid"><div class="wr21-card"><h3>Warehouse Receipt</h3><div class="wr21-fields"><label class="wr21-field"><span>WR number</span><input value="${esc(S.wr.receipt_number)}" readonly></label><label class="wr21-field"><span>Status</span><input value="${esc(S.wr.status)}" readonly></label><label class="wr21-field"><span>Created</span><input value="${esc(fmt(S.wr.created_at))}" readonly></label><label class="wr21-field"><span>Received</span><input value="${esc(fmt(S.wr.received_at))}" readonly></label></div><div class="wr21-partygrid" style="margin-top:12px">${partyCard('customer')}${partyCard('shipper')}${partyCard('consignee')}</div></div><div class="wr21-card"><h3>Readiness</h3><p>${missing().length?'Items still need attention before final completion.':'No blocking items detected.'}</p>${missing().map(x=>`<span class="wr21-badge warn" style="margin:4px">${esc(x)}</span>`).join('')||'<span class="wr21-badge good">Ready</span>'}<div class="wr21-actions"><button data-workflow-edit>Edit workflow</button></div></div></div>`}
function partiesView(){return `<div class="wr21-between"><div><h2 style="margin:0">Parties</h2><p style="color:#8194a8">Customer, Shipper and Consignee are the WR basics. Saved master records bring address and contact details into the WR and PDF.</p></div><button class="wr21-iconbtn" data-edit-parties>✎ Edit</button></div><div class="wr21-partygrid" style="margin-top:13px">${partyCard('customer')}${partyCard('shipper')}${partyCard('consignee')}</div>`}
function arrivalView(){const v=S.visit||{};return `<div class="wr21-card"><div class="wr21-between"><h3>Dock visit</h3><button data-edit-arrival>✎ Edit in Guided</button></div>${timeline()}<div class="wr21-fields"><label class="wr21-field"><span>Carrier</span><input value="${esc(v.carrier_name_snapshot||'')}" readonly></label><label class="wr21-field"><span>Driver</span><input value="${esc(v.driver_name||'')}" readonly></label><label class="wr21-field"><span>BOL</span><input value="${esc(v.bol_number||'')}" readonly></label><label class="wr21-field"><span>PRO / tracking</span><input value="${esc(v.pro_number||v.tracking_number||'')}" readonly></label><label class="wr21-field"><span>Door</span><input value="${esc(v.door||'')}" readonly></label><label class="wr21-field"><span>Seal / trailer</span><input value="${esc([v.seal_number,v.trailer_number].filter(Boolean).join(' / '))}" readonly></label></div></div>`}
function flatCargo(){const out=[];const walk=(x,d=0)=>{out.push([x,d]);children(x.id).forEach(c=>walk(c,d+1))};roots().forEach(x=>walk(x));return out}
function cargoView(){const q=cargoQuery.trim().toLowerCase(),rows=flatCargo().filter(([x])=>!q||[x.handling_unit_code,x.package_type,x.description,x.sku,x.part_number,x.lot_number,x.serial_number].some(v=>String(v||'').toLowerCase().includes(q)));return `<div class="wr21-cargobar"><div><h3 style="margin:0">Physical cargo</h3><p style="margin:4px 0 0;color:#7f92a8;font-size:10px">Outer handling units contain nested cargo. Drafts autosave while you work.</p></div><div style="display:flex;gap:7px;flex-wrap:wrap"><input class="wr21-search" id="cargo-q" value="${esc(cargoQuery)}" placeholder="Search cargo, SKU, part…"><button class="primary" data-cargo-add>＋ Cargo</button></div></div>${rows.length?`<div class="wr21-bulk"><label><input type="checkbox" class="wr21-check" data-cargo-all> Select all</label><button class="danger" data-cargo-delete-selected ${selectedCargo.size?'':'disabled'}>Delete selected${selectedCargo.size?` (${selectedCargo.size})`:''}</button></div><div class="wr21-tablewrap"><table class="wr21-table"><thead><tr><th></th><th>Cargo</th><th>Description / part</th><th>Qty</th><th>Weight</th><th>Dimensions</th><th>Location</th><th>Controls</th><th>Actions</th></tr></thead><tbody>${rows.map(([x,d])=>cargoRow(x,d)).join('')}</tbody></table></div>`:'<div class="wr21-empty">No cargo recorded yet. Add the outer handling unit first.</div>'}`}
function cargoRow(x,d){const loc=S.locations.find(l=>l.id===(x.current_location_id||x.warehouse_location_id)),photos=S.docs.filter(z=>z.cargo_unit_id===x.id&&['PHOTO','DAMAGE_PHOTO','DG_LABEL'].includes(String(z.category||'').toUpperCase())).length,controls=S.controls.filter(z=>z.cargo_unit_id===x.id).map(z=>z.control_type).join(' · '),dims=x.length_in&&x.width_in&&x.height_in?`${Number(x.length_in).toFixed(1)}×${Number(x.width_in).toFixed(1)}×${Number(x.height_in).toFixed(1)} in`:'—',draft=x.metadata?.editor_draft;return `<tr><td><input class="wr21-check" type="checkbox" data-cargo-select="${x.id}" ${selectedCargo.has(x.id)?'checked':''}></td><td><span class="wr21-indent ${d?'child':''}">${d?'↳':'▾'} ${esc(x.handling_unit_code||'')} ${esc(x.package_type||'')}</span>${draft?' <span class="wr21-badge warn">draft</span>':''}</td><td><b>${esc(x.description||'—')}</b><br><small>${esc(x.part_number||x.sku||'')}</small></td><td>${esc(x.quantity||0)} ${esc(x.uom||'')}</td><td>${x.weight_lb?`${Number(x.weight_lb).toFixed(1)} lb`:'—'}</td><td>${dims}</td><td>${esc(loc?.code||'—')}</td><td>${controls?`<span class="wr21-badge warn">${esc(controls)}</span>`:''}${photos?` <span class="wr21-badge">📷 ${photos}</span>`:''}</td><td><div class="wr21-rowactions"><button data-cargo-edit="${x.id}">Edit</button><button data-cargo-inside="${x.id}">+ Inside</button><button data-cargo-photo="${x.id}">Photo</button><button data-cargo-control="${x.id}">DG / Customs</button><button data-cargo-exception="${x.id}">Exception</button><button data-cargo-label="${x.id}">Label</button><button class="danger" data-cargo-delete="${x.id}">Delete</button></div></td></tr>`}
function documentsView(){const groups={};for(const d of S.docs){const key=docGroup==='cargo'?(d.cargo_unit_id?S.cargo.find(x=>x.id===d.cargo_unit_id)?.handling_unit_code||S.cargo.find(x=>x.id===d.cargo_unit_id)?.package_type||'Cargo':'Receipt-level'):(d.category||d.document_type||'Other');(groups[key] ||= []).push(d)}return `<div class="wr21-docbar"><div><h3 style="margin:0">Documents</h3><p style="margin:4px 0 0;color:#7f92a8;font-size:10px">Organize by document type or cargo association.</p></div><div style="display:flex;gap:7px;flex-wrap:wrap"><select id="doc-group" class="wr21-search"><option value="category" ${docGroup==='category'?'selected':''}>By category</option><option value="cargo" ${docGroup==='cargo'?'selected':''}>By cargo</option></select><button data-doc-scan>Scan</button><button class="primary" data-doc-upload>Upload</button></div></div>${S.docs.length?`<div class="wr21-bulk"><label><input type="checkbox" class="wr21-check" data-doc-all> Select all</label><button data-doc-download-selected ${selectedDocs.size?'':'disabled'}>Download selected${selectedDocs.size?` (${selectedDocs.size})`:''}</button><button data-doc-share-selected ${selectedDocs.size?'':'disabled'}>Share selected</button><button data-doc-download-all>Download all</button></div>`:''}<div class="wr21-docgroups">${Object.entries(groups).map(([k,ds])=>`<section class="wr21-docgroup"><h4>${esc(k)} · ${ds.length}</h4>${ds.map(docRow).join('')}</section>`).join('')||'<div class="wr21-empty">No documents yet. Scan or upload the first document.</div>'}</div>`}
function docRow(d){return `<div class="wr21-docrow"><input type="checkbox" class="wr21-check" data-doc-select="${d.id}" ${selectedDocs.has(d.id)?'checked':''}><div class="wr21-docicon">▤</div><div><b>${esc(d.display_name||d.file_name||d.document_type||'Document')}</b><small>${esc(d.category||d.document_type||'OTHER')} · ${fmt(d.created_at)}${d.extraction?' · OCR data available':''}</small></div><div class="wr21-docactions"><button data-doc-preview="${d.id}">Preview</button><button data-doc-download="${d.id}">Download</button><button data-doc-share="${d.id}">Share</button><button data-doc-tag="${d.id}">Tag</button></div></div>`}
function complianceView(){const types=['DG','IN_BOND_7512','FTZ'];return `<div class="wr21-between"><div><h2 style="margin:0">Compliance controls</h2><p style="color:#8093a8">Structured control state, not notes.</p></div><button data-control-add>＋ Add control</button></div><div class="wr21-controlgrid" style="margin-top:13px">${types.map(t=>{const a=S.controls.filter(x=>x.control_type===t);return `<div class="wr21-control"><div class="state">${a.length?(a.every(x=>x.verified)?'verified':'pending'):'not applicable'}</div><h4>${t==='IN_BOND_7512'?'In-bond / 7512':t}</h4><p>${a.length?`${a.length} control${a.length===1?'':'s'} · ${a.filter(x=>x.verified).length} verified`:'No active control.'}</p>${a.map(x=>`<span class="wr21-badge ${x.verified?'good':'warn'}">${esc(x.status||'pending')}</span>`).join(' ')}</div>`}).join('')}</div>`}
function exceptionsView(){return `<div class="wr21-between"><div><h2 style="margin:0">Exception ledger</h2><p style="color:#8093a8">Damage, shortage, overage, seal discrepancies, holds and other operational issues.</p></div><button data-exception-add>＋ Exception</button></div><div class="wr21-docgroups">${S.flags.map(f=>`<div class="wr21-docgroup"><div class="wr21-between"><div><span class="wr21-badge warn">${esc(f.flag_type)}</span><h4 style="margin:8px 0 0">${esc(f.notes||'No notes')}</h4><small style="color:#71869d">${fmt(f.created_at)} · ${esc(f.severity||'')}</small></div><button data-flag-clear="${f.id}">Resolve</button></div></div>`).join('')||'<div class="wr21-empty">No active exceptions.</div>'}</div>`}
function activityView(){return `<div class="wr21-docgroups">${S.events.slice().reverse().map(e=>`<div class="wr21-docgroup"><b>${esc(e.event_type)}</b><small style="display:block;color:#71869d;margin-top:4px">${fmt(e.created_at)}</small></div>`).join('')||'<div class="wr21-empty">No workflow activity yet.</div>'}</div>`}
function putawayView(){return roots().filter(x=>!x.metadata?.editor_draft).map(x=>`<div class="wr21-card" style="margin-top:9px"><div class="wr21-between"><div><b>${esc(x.handling_unit_code||x.package_type)}</b><div style="color:#71869d;font-size:9px">${esc(x.description||'')}</div></div><button data-putaway="${x.id}">${x.current_location_id||x.warehouse_location_id?'Change location':'Assign location'}</button></div></div>`).join('')||'<div class="wr21-empty">Add cargo before put-away.</div>'}

function render(){document.body.classList.add('wr21-active');document.body.classList.remove('wr19-active');main.innerHTML=`<section class="wr21">${head()}${mode==='guided'?guided():record()}<input id="wr21-upload" type="file" hidden multiple></section>`;ensureBack();bind()}
async function rerender({keepManual=true}={}){await refresh();if(!keepManual)manualStep=null;render()}
function ensureBack(){let b=document.querySelector('.wr21-back');if(!b){b=document.createElement('button');b.className='wr21-back';b.textContent='‹ Receipts';b.onclick=()=>{document.body.classList.remove('wr21-active');window.nodaraSetActive?.('wr');document.querySelector('[data-go="wr"],[data-route="wr"],[data-view="wr"]')?.click()||history.back()};document.body.appendChild(b)}}

function previewEntity(inp,e){const p=inp.closest('[data-smart-wrap]')?.querySelector('[data-preview]');if(!p)return;if(!e){p.hidden=true;return}const a=S.addresses.find(x=>x.entity_id===e.id&&x.is_primary)||S.addresses.find(x=>x.entity_id===e.id),c=S.contacts.find(x=>x.entity_id===e.id&&x.is_primary)||S.contacts.find(x=>x.entity_id===e.id);p.innerHTML=`${esc([a?.line1,[a?.city,a?.state_region,a?.postal_code].filter(Boolean).join(' ')].filter(Boolean).join(' · ')||'No saved address')}${c?`<br>${esc([c.name,c.phone,c.email].filter(Boolean).join(' · '))}`:''}`;p.hidden=false}
function bindSmart(){main.querySelectorAll('[data-smart]').forEach(inp=>{const menu=inp.parentElement.querySelector('.wr21-smartmenu');const show=()=>{const q=inp.value.trim().toLowerCase(),rows=S.entities.filter(e=>!q||e.name.toLowerCase().includes(q)||String(e.code||'').toLowerCase().includes(q)).slice(0,7);menu.innerHTML=rows.map(e=>{const a=S.addresses.find(x=>x.entity_id===e.id&&x.is_primary)||S.addresses.find(x=>x.entity_id===e.id);return `<button data-smartpick="${e.id}"><b>${esc(e.name)}</b><small>${esc([a?.line1,a?.city,a?.state_region].filter(Boolean).join(' · ')||e.code||'Saved record')}</small></button>`}).join('')+`<button data-use-once>Use “${esc(inp.value||'typed value')}” for this WR only</button><button data-smart-new>＋ Create new master record</button>`;menu.hidden=false;menu.querySelectorAll('[data-smartpick]').forEach(b=>b.onclick=()=>{const e=ent(b.dataset.smartpick);inp.value=e?.name||'';inp.dataset.entityId=b.dataset.smartpick;previewEntity(inp,e);menu.hidden=true});menu.querySelector('[data-use-once]')?.addEventListener('click',()=>{delete inp.dataset.entityId;previewEntity(inp,null);menu.hidden=true});menu.querySelector('[data-smart-new]')?.addEventListener('click',()=>{menu.hidden=true;entityModal(inp.dataset.smart,inp.value,created=>{inp.value=created.name;inp.dataset.entityId=created.id;previewEntity(inp,created)})})};inp.addEventListener('input',()=>{delete inp.dataset.entityId;previewEntity(inp,null);show()});inp.addEventListener('focus',show);inp.addEventListener('blur',()=>setTimeout(()=>menu.hidden=true,180));if(inp.dataset.entityId)previewEntity(inp,ent(inp.dataset.entityId))})}

function modal(html,{onClose}={}){const back=document.createElement('div'),box=document.createElement('div');back.className='wr21-modalback';box.className='wr21-modal';box.innerHTML=html;document.body.append(back,box);let closed=false;const close=()=>{if(closed)return;closed=true;back.remove();box.remove();onClose?.()};back.onclick=close;box.querySelector('[data-x]')?.addEventListener('click',close);return{box,close}}
function entityModal(role,name='',cb=()=>{}){const m=modal(`<div class="wr21-modalhead"><div><div class="wr21-k">QUICK CREATE</div><h3>New ${esc(role)} record</h3></div><button class="wr21-x" data-x>×</button></div><div class="wr21-fields"><label class="wr21-field"><span>Name</span><input id="qe-name" value="${esc(name)}"></label><label class="wr21-field"><span>Code</span><input id="qe-code"></label><label class="wr21-field"><span>Address</span><input id="qe-line1"></label><label class="wr21-field"><span>City</span><input id="qe-city"></label><label class="wr21-field"><span>State</span><input id="qe-state"></label><label class="wr21-field"><span>Postal code</span><input id="qe-postal"></label><label class="wr21-field"><span>Contact</span><input id="qe-contact"></label><label class="wr21-field"><span>Email</span><input id="qe-email"></label><label class="wr21-field"><span>Phone</span><input id="qe-phone"></label></div><div class="wr21-actions"><button class="primary" id="qe-save">Create & select</button></div>`);m.box.querySelector('#qe-save').onclick=async()=>{const n=m.box.querySelector('#qe-name').value.trim();if(!n)return;const{data:e,error}=await supabase.from('entities').insert({organization_id:S.wr.organization_id,name:n,code:m.box.querySelector('#qe-code').value.trim()||null,roles:[String(role||'PARTY').toUpperCase()],email:m.box.querySelector('#qe-email').value.trim()||null,phone:m.box.querySelector('#qe-phone').value.trim()||null}).select().single();if(error)return alert(error.message);const line=m.box.querySelector('#qe-line1').value.trim();if(line)await supabase.from('entity_addresses').insert({organization_id:S.wr.organization_id,entity_id:e.id,address_type:'MAIN',line1:line,city:m.box.querySelector('#qe-city').value.trim()||null,state_region:m.box.querySelector('#qe-state').value.trim()||null,postal_code:m.box.querySelector('#qe-postal').value.trim()||null,is_primary:true,active:true});const cn=m.box.querySelector('#qe-contact').value.trim();if(cn)await supabase.from('entity_contacts').insert({organization_id:S.wr.organization_id,entity_id:e.id,name:cn,email:m.box.querySelector('#qe-email').value.trim()||null,phone:m.box.querySelector('#qe-phone').value.trim()||null,is_primary:true,active:true});await refresh();cb(ent(e.id)||e);m.close();toast('Record created ✓')}}

async function ensureDraft(x,parent){if(x)return x;const type=parent?'BOX':'PALLET',uom=packageTypes().find(z=>z[0]===type)?.[1]||type;const{data,error}=await supabase.from('cargo_units').insert({organization_id:S.wr.organization_id,job_id:S.wr.job_id,parent_id:parent?.id||null,package_type:type,quantity:1,uom,status:'received',processing_status:'pending',metadata:{editor_draft:true}}).select().single();if(error){alert(error.message);return null}S.cargo.push(data);return data}
async function cargoModal(existing=null,parent=null){let x=await ensureDraft(existing,parent);if(!x)return;let dirty=!!existing,evidenceUsed=false,saveTimer=null,inventoryItemId=x.inventory_item_id||null;const siblings=S.cargo.filter(z=>z.parent_id===x.parent_id);const parentRow=x.parent_id?S.cargo.find(z=>z.id===x.parent_id):null;const weightUnit=x.metadata?.input_weight_unit||S.units?.weight_unit||'LB',dimUnit=x.metadata?.input_dimension_unit||S.units?.dimension_unit||'IN';const displayWeight=x.weight_lb==null?'':(weightUnit==='KG'?Number(x.weight_lb)/2.2046226218:Number(x.weight_lb));const displayDim=(n)=>n==null?'':(dimUnit==='CM'?Number(n)*2.54:Number(n));const nav=`<div class="wr21-cargonav">${parentRow?`<button data-nav-cargo="${parentRow.id}">← ${esc(parentRow.handling_unit_code||parentRow.package_type)}</button>`:''}${siblings.map(z=>`<button data-nav-cargo="${z.id}" class="${z.id===x.id?'active':''}">${esc(z.handling_unit_code||z.package_type||'Cargo')}</button>`).join('')}<button data-new-inside>＋ Inside</button></div>`;const m=modal(`<div class="wr21-modalhead"><div><div class="wr21-k">CARGO · AUTOSAVE</div><h3>${esc(x.handling_unit_code||x.package_type||'Cargo')}</h3></div><button class="wr21-x" data-x>×</button></div>${nav}<div class="wr21-compact"><div class="wr21-pill"><input id="c-qty" type="number" value="${esc(x.quantity||1)}"></div><label class="wr21-field"><span>Package type</span><select id="c-type">${packageTypes().map(([t])=>`<option ${t===x.package_type?'selected':''}>${t}</option>`).join('')}<option value="__NEW__">＋ Add type…</option></select></label><label class="wr21-field wr21-itemmenu"><span>Description / part / SKU</span><input id="c-desc" value="${esc(x.description||'')}" placeholder="Describe or search item master"><div class="wr21-itemresults" hidden></div></label></div><div class="wr21-fields"><label class="wr21-field"><span>Gross weight</span><div class="wr21-pill"><input id="c-weight" type="number" step="any" value="${esc(displayWeight)}"><select id="c-wu"><option ${weightUnit==='LB'?'selected':''}>LB</option><option ${weightUnit==='KG'?'selected':''}>KG</option></select></div></label><label class="wr21-field"><span>Dimensions</span><div class="wr21-pill"><input id="c-l" type="number" step="any" placeholder="L" value="${esc(displayDim(x.length_in))}"><input id="c-w" type="number" step="any" placeholder="W" value="${esc(displayDim(x.width_in))}"><input id="c-h" type="number" step="any" placeholder="H" value="${esc(displayDim(x.height_in))}"><select id="c-du"><option ${dimUnit==='IN'?'selected':''}>IN</option><option ${dimUnit==='CM'?'selected':''}>CM</option></select></div></label></div><details class="wr21-details"><summary>Part / inventory details</summary><div class="wr21-fields"><label class="wr21-field wr21-itemmenu"><span>Part number</span><input id="c-part" value="${esc(x.part_number||'')}" placeholder="Search saved part"><div class="wr21-itemresults" hidden></div></label><label class="wr21-field"><span>SKU</span><input id="c-sku" value="${esc(x.sku||'')}"></label><label class="wr21-field"><span>Lot</span><input id="c-lot" value="${esc(x.lot_number||'')}"></label><label class="wr21-field"><span>Serial</span><input id="c-serial" value="${esc(x.serial_number||'')}"></label></div></details><div class="wr21-metrics"><div class="wr21-metric"><small>UOM</small><b id="c-uom">${esc(x.uom||'—')}</b></div><div class="wr21-metric"><small>Volume</small><b id="c-vol">—</b></div><div class="wr21-metric"><small>Chargeable</small><b id="c-chg">—</b></div></div><div class="wr21-draftstate" id="c-state">Autosaved draft</div><div class="wr21-actions"><button class="wr21-iconbtn" id="c-photo">${cameraIcon} Photo</button><button id="c-control">DG / Customs</button><button id="c-exception">Exception</button><button id="c-delete" style="color:#efa3a3">Delete</button><button class="primary" id="c-done">Done</button></div>`,{onClose:()=>clearTimeout(saveTimer)});
 const q=id=>m.box.querySelector(id),num=id=>q(id)?.value===''?null:Number(q(id)?.value),type=q('#c-type');
 const calc=()=>{const pu=packageTypes().find(z=>z[0]===type.value);q('#c-uom').textContent=pu?.[1]||type.value;let l=num('#c-l'),w=num('#c-w'),h=num('#c-h');if(q('#c-du').value==='CM'){l=l/2.54;w=w/2.54;h=h/2.54}const cbm=l&&w&&h?l*w*h*0.000016387064:0;q('#c-vol').textContent=cbm?cbm.toFixed(3)+' m³':'—';q('#c-chg').textContent=l&&w&&h?(l*w*h/166).toFixed(1)+' lb':'—'};
 const payload=()=>{let wt=num('#c-weight');if(wt!=null&&q('#c-wu').value==='KG')wt*=2.2046226218;let l=num('#c-l'),w=num('#c-w'),h=num('#c-h');if(q('#c-du').value==='CM'){l=l==null?null:l/2.54;w=w==null?null:w/2.54;h=h==null?null:h/2.54}const pu=packageTypes().find(z=>z[0]===type.value);return{package_type:type.value,quantity:num('#c-qty')||1,uom:pu?.[1]||type.value,description:q('#c-desc').value.trim()||null,inventory_item_id:inventoryItemId,part_number:q('#c-part').value.trim()||null,sku:q('#c-sku').value.trim()||null,lot_number:q('#c-lot').value.trim()||null,serial_number:q('#c-serial').value.trim()||null,weight_lb:wt,length_in:l,width_in:w,height_in:h,metadata:{...(x.metadata||{}),editor_draft:true,input_weight_unit:q('#c-wu').value,input_dimension_unit:q('#c-du').value}}};
 const autosave=async()=>{dirty=true;clearTimeout(saveTimer);q('#c-state').textContent='Saving…';saveTimer=setTimeout(async()=>{const{error}=await supabase.from('cargo_units').update(payload()).eq('id',x.id);q('#c-state').textContent=error?'Save failed · '+error.message:'Saved';if(!error)Object.assign(x,payload());calc()},350)};
 m.box.querySelectorAll('input,select').forEach(e=>{e.addEventListener('input',autosave);e.addEventListener('change',autosave)});type.onchange=()=>{if(type.value==='__NEW__')packageTypeModal(created=>{const o=document.createElement('option');o.value=created.code;o.textContent=created.label;type.insertBefore(o,type.lastElementChild);type.value=created.code;autosave();calc()});else{autosave();calc()}};calc();
 const itemSearch=(inp)=>{const results=inp.parentElement.querySelector('.wr21-itemresults');const show=()=>{const val=inp.value.trim().toLowerCase();const owner=S.job?.customer_id;const items=S.items.filter(i=>(!owner||!i.owner_entity_id||i.owner_entity_id===owner)&&(!val||[i.part_number,i.sku,i.description,i.metadata?.barcode].some(v=>String(v||'').toLowerCase().includes(val)))).slice(0,7);results.innerHTML=items.map(i=>`<button data-item="${i.id}"><b>${esc(i.part_number||i.sku||'Item')}</b><small>${esc([i.sku,i.description].filter(Boolean).join(' · '))}</small></button>`).join('')+`<button data-item-new>＋ Create new part master</button>`;results.hidden=false;results.querySelectorAll('[data-item]').forEach(b=>b.onclick=()=>{const i=S.items.find(z=>z.id===b.dataset.item);inventoryItemId=i.id;q('#c-part').value=i.part_number||'';q('#c-sku').value=i.sku||'';q('#c-desc').value=i.description||q('#c-desc').value;const md=i.metadata||{};if(md.weight_lb!=null){q('#c-wu').value='LB';q('#c-weight').value=md.weight_lb}if(md.length_in!=null){q('#c-du').value='IN';q('#c-l').value=md.length_in;q('#c-w').value=md.width_in??'';q('#c-h').value=md.height_in??''}results.hidden=true;autosave();calc()});results.querySelector('[data-item-new]')?.addEventListener('click',()=>{results.hidden=true;itemModal(inp.value,i=>{inventoryItemId=i.id;q('#c-part').value=i.part_number||'';q('#c-sku').value=i.sku||'';q('#c-desc').value=i.description||q('#c-desc').value;autosave()})})};inp.addEventListener('input',show);inp.addEventListener('focus',show);inp.addEventListener('blur',()=>setTimeout(()=>results.hidden=true,180))};itemSearch(q('#c-part'));itemSearch(q('#c-desc'));
 m.box.querySelectorAll('[data-nav-cargo]').forEach(b=>b.onclick=async()=>{await supabase.from('cargo_units').update(payload()).eq('id',x.id);m.close();await refresh();cargoModal(S.cargo.find(z=>z.id===b.dataset.navCargo))});q('[data-new-inside]')?.addEventListener('click',async()=>{await supabase.from('cargo_units').update(payload()).eq('id',x.id);m.close();await refresh();cargoModal(null,S.cargo.find(z=>z.id===x.id))});
 q('#c-photo').onclick=async()=>{evidenceUsed=true;await supabase.from('cargo_units').update(payload()).eq('id',x.id);window.NodaraWRMedia?.openCargoCamera?.({cargoId:x.id})};q('#c-control').onclick=async()=>{evidenceUsed=true;await supabase.from('cargo_units').update(payload()).eq('id',x.id);controlModal(x.id)};q('#c-exception').onclick=async()=>{evidenceUsed=true;await supabase.from('cargo_units').update(payload()).eq('id',x.id);exceptionModal(x.id)};q('#c-delete').onclick=async()=>{if(!confirm('Delete this cargo and all nested cargo?'))return;await deleteCargo([x.id]);m.close();await rerender()};q('#c-done').onclick=async()=>{clearTimeout(saveTimer);const p=payload();p.processing_status='processed';p.status='received';p.metadata={...p.metadata,editor_draft:false};const{error}=await supabase.from('cargo_units').update(p).eq('id',x.id);if(error)return alert(error.message);m.close();manualStep=null;toast('Cargo saved ✓');await rerender({keepManual:false})}}
function itemModal(seed='',cb=()=>{}){if(!S.job?.customer_id)return alert('Select the customer first to create a reusable Part Master record. You can still type a part/SKU for this WR only.');const m=modal(`<div class="wr21-modalhead"><div><div class="wr21-k">PART MASTER</div><h3>New part</h3></div><button class="wr21-x" data-x>×</button></div><div class="wr21-fields"><label class="wr21-field"><span>Part number</span><input id="im-part" value="${esc(seed)}"></label><label class="wr21-field"><span>SKU</span><input id="im-sku"></label><label class="wr21-field" style="grid-column:1/-1"><span>Description</span><input id="im-desc"></label><label class="wr21-field"><span>Base UOM</span><input id="im-uom" value="EA"></label></div><div class="wr21-actions"><button class="primary" id="im-save">Create & use</button></div>`);m.box.querySelector('#im-save').onclick=async()=>{const part=m.box.querySelector('#im-part').value.trim();if(!part)return alert('Part number is required.');const{data,error}=await supabase.from('inventory_items').insert({organization_id:S.wr.organization_id,owner_entity_id:S.job.customer_id,part_number:part,sku:m.box.querySelector('#im-sku').value.trim()||null,description:m.box.querySelector('#im-desc').value.trim()||null,base_uom:m.box.querySelector('#im-uom').value.trim()||'EA',metadata:{}}).select().single();if(error)return alert(error.message);S.items.push(data);cb(data);m.close();toast('Part master created ✓')}}
function packageTypeModal(cb){const m=modal(`<div class="wr21-modalhead"><h3>New package type</h3><button class="wr21-x" data-x>×</button></div><div class="wr21-fields"><label class="wr21-field"><span>Name / code</span><input id="pt-code" placeholder="BUNDLE"></label><label class="wr21-field"><span>Default UOM</span><input id="pt-uom" placeholder="BDL"></label></div><div class="wr21-actions"><button class="primary" id="pt-save">Add type</button></div>`);m.box.querySelector('#pt-save').onclick=async()=>{const code=m.box.querySelector('#pt-code').value.trim().toUpperCase(),uom=m.box.querySelector('#pt-uom').value.trim().toUpperCase();if(!code)return;const{data,error}=await supabase.from('organization_reference_options').insert({organization_id:S.wr.organization_id,option_group:'PACKAGE_TYPE',code,label:code,uom:uom||code,active:true}).select().single();if(error)return alert(error.message);S.options.push(data);cb(data);m.close()}}
function controlModal(cargoId=null){const m=modal(`<div class="wr21-modalhead"><h3>Compliance control</h3><button class="wr21-x" data-x>×</button></div><div class="wr21-fields"><label class="wr21-field"><span>Control</span><select id="ct-type"><option value="DG">Dangerous Goods</option><option value="IN_BOND_7512">In-bond / 7512</option><option value="FTZ">FTZ</option></select></label><label class="wr21-field"><span>Status</span><select id="ct-status"><option>pending</option><option>verified</option><option>hold</option><option>released</option></select></label><label class="wr21-field"><span>Reference / UN / bond</span><input id="ct-ref"></label><label class="wr21-field"><span>Class / type / detail</span><input id="ct-detail"></label></div><div class="wr21-actions"><button class="primary" id="ct-save">Add control</button></div>`);m.box.querySelector('#ct-save').onclick=async()=>{const status=m.box.querySelector('#ct-status').value,{error}=await supabase.from('receiving_controls').insert({organization_id:S.wr.organization_id,warehouse_receipt_id:wrId,cargo_unit_id:cargoId,control_type:m.box.querySelector('#ct-type').value,status,verified:['verified','released'].includes(status),verified_at:['verified','released'].includes(status)?new Date().toISOString():null,verified_by:['verified','released'].includes(status)?await uid():null,details:{reference:m.box.querySelector('#ct-ref').value.trim(),detail:m.box.querySelector('#ct-detail').value.trim()}});if(error)return alert(error.message);m.close();await rerender()}}
function exceptionModal(cargoId=null,preset='DAMAGE'){const m=modal(`<div class="wr21-modalhead"><h3>Add exception</h3><button class="wr21-x" data-x>×</button></div><div class="wr21-fields"><label class="wr21-field"><span>Type</span><select id="ex-type">${['DAMAGE','SHORTAGE','OVERAGE','WET','OPEN_PACKAGE','SEAL_DISCREPANCY','WRONG_CARGO','UNKNOWN_CARGO','MEASUREMENT_DISCREPANCY','HOLD','OTHER'].map(x=>`<option ${x===preset?'selected':''}>${x}</option>`).join('')}</select></label><label class="wr21-field"><span>Severity</span><select id="ex-sev"><option>info</option><option selected>warning</option><option>critical</option></select></label><label class="wr21-field" style="grid-column:1/-1"><span>Notes</span><textarea id="ex-notes"></textarea></label></div><div class="wr21-actions"><button class="primary" id="ex-save">Create exception</button></div>`);m.box.querySelector('#ex-save').onclick=async()=>{const{error}=await supabase.from('operational_flags').insert({organization_id:S.wr.organization_id,warehouse_receipt_id:wrId,cargo_unit_id:cargoId,flag_type:m.box.querySelector('#ex-type').value,severity:m.box.querySelector('#ex-sev').value,active:true,source:'USER',notes:m.box.querySelector('#ex-notes').value.trim()||null,created_by:await uid()});if(error)return alert(error.message);m.close();await rerender()}}
function putawayModal(id){const x=S.cargo.find(z=>z.id===id),m=modal(`<div class="wr21-modalhead"><h3>Put away ${esc(x?.handling_unit_code||x?.package_type||'cargo')}</h3><button class="wr21-x" data-x>×</button></div><div class="wr21-actions"><button class="wr21-iconbtn" id="pa-scan">${scanIcon} Scan location</button></div><label class="wr21-field"><span>Location</span><select id="pa-loc">${S.locations.map(l=>`<option value="${l.id}" ${(x.current_location_id||x.warehouse_location_id)===l.id?'selected':''}>${esc(l.code)} · ${esc(l.name||'')}</option>`).join('')}</select></label><div class="wr21-actions"><button class="primary" id="pa-save">Assign location</button></div>`);m.box.querySelector('#pa-scan').onclick=()=>window.nodaraScanTask?.({title:'Scan destination location',onScan:async code=>{const l=S.locations.find(z=>z.code===code);if(!l)return false;m.box.querySelector('#pa-loc').value=l.id;return true}});m.box.querySelector('#pa-save').onclick=async()=>{const loc=m.box.querySelector('#pa-loc').value,{error}=await supabase.from('cargo_units').update({current_location_id:loc,warehouse_location_id:loc}).eq('id',id);if(error)return alert(error.message);m.close();await rerender()}}

async function deleteCargo(ids){const{data:all}=await supabase.from('cargo_units').select('id,parent_id').eq('job_id',S.wr.job_id);const set=new Set(ids);let changed=true;while(changed){changed=false;for(const x of all||[])if(x.parent_id&&set.has(x.parent_id)&&!set.has(x.id)){set.add(x.id);changed=true}}const{error}=await supabase.from('cargo_units').delete().in('id',[...set]);if(error)alert(error.message);else{selectedCargo.clear();toast('Cargo deleted');await rerender()}}

function docMetaModal(kind='upload',docId=null){const custom=(S.options||[]).filter(x=>x.option_group==='DOCUMENT_TAG'&&x.active).map(x=>x.code),tags=['BOL','PACKING_LIST','COMMERCIAL_INVOICE','7512','POD','DG_DOCUMENT','DRIVER_ID','PHOTO','OTHER',...custom.filter(x=>!['BOL','PACKING_LIST','COMMERCIAL_INVOICE','7512','POD','DG_DOCUMENT','DRIVER_ID','PHOTO','OTHER'].includes(x))];const m=modal(`<div class="wr21-modalhead"><h3>${docId?'Tag document':kind==='scan'?'Scan document':'Upload document'}</h3><button class="wr21-x" data-x>×</button></div><div class="wr21-fields"><label class="wr21-field"><span>Document type</span><select id="dm-tag">${tags.map(t=>`<option>${esc(t)}</option>`).join('')}<option value="__NEW__">＋ Add tag…</option></select></label><label class="wr21-field"><span>Associate to cargo</span><select id="dm-cargo"><option value="">Receipt-level</option>${flatCargo().map(([x,d])=>`<option value="${x.id}">${'— '.repeat(d)}${esc(x.handling_unit_code||x.package_type)}</option>`).join('')}</select></label></div><div class="wr21-actions"><button class="primary" id="dm-go">${docId?'Apply tag':kind==='scan'?'Open scanner':'Choose file'}</button></div>`);const tag=m.box.querySelector('#dm-tag');tag.onchange=()=>{if(tag.value!=='__NEW__')return;const val=prompt('New reusable document tag');if(!val){tag.value='OTHER';return}const code=val.trim().toUpperCase().replace(/\s+/g,'_');supabase.from('organization_reference_options').insert({organization_id:S.wr.organization_id,option_group:'DOCUMENT_TAG',code,label:val.trim(),active:true}).then(({data,error})=>{if(!error){S.options.push({option_group:'DOCUMENT_TAG',code,label:val.trim(),active:true});const o=document.createElement('option');o.value=code;o.textContent=val.trim();tag.insertBefore(o,tag.lastElementChild);tag.value=code}})};m.box.querySelector('#dm-go').onclick=async()=>{const meta={category:tag.value,cargoId:m.box.querySelector('#dm-cargo').value||null};if(docId){const{error}=await supabase.from('documents').update({category:meta.category,cargo_unit_id:meta.cargoId}).eq('id',docId);if(error)return alert(error.message);m.close();await rerender();return}if(kind==='scan'){m.close();window.NodaraWRScanner?.open?.({category:meta.category,kind:meta.category==='DRIVER_ID'?'DRIVER_ID':null});return}pendingDocMeta=meta;m.close();main.querySelector('#wr21-upload')?.click()}}
async function uploadFiles(e){const meta=pendingDocMeta||{category:'OTHER',cargoId:null};for(const f of e.target.files||[]){const{data:tx}=await supabase.from('transactions').select('id').eq('transaction_type','WAREHOUSE_RECEIPT').eq('domain_record_id',wrId).maybeSingle();if(!tx?.id)return alert('WR transaction is missing.');const path=`${S.wr.organization_id}/${tx.id}/transaction/${crypto.randomUUID()}_${f.name.replace(/[^a-zA-Z0-9._-]/g,'_')}`,up=await supabase.storage.from('nodara-documents').upload(path,f,{contentType:f.type,upsert:false});if(up.error)return alert(up.error.message);const reg=await supabase.rpc('nodara_register_document',{p_transaction_id:tx.id,p_document_type:meta.category||'OTHER',p_storage_path:path,p_file_name:f.name,p_mime_type:f.type,p_cargo_object_id:null,p_entity_id:null,p_template_id:null,p_display_name:f.name,p_document_number:null,p_category:meta.category||'OTHER',p_link_role:'SUPPORTING',p_source:'USER',p_status:'ACTIVE',p_notes:null,p_metadata:{uploaded_from:'WR_V21',cargo_unit_id:meta.cargoId},p_provenance:{source_type:'USER',surface:'WR_V21'}});if(reg.error)return alert(reg.error.message);if(meta.cargoId&&reg.data){const id=typeof reg.data==='string'?reg.data:reg.data.id; if(id)await supabase.from('documents').update({cargo_unit_id:meta.cargoId}).eq('id',id)}}pendingDocMeta=null;e.target.value='';await rerender()}
async function signedDoc(d){const{data}=await supabase.storage.from('nodara-documents').createSignedUrl(d.storage_path,180);return data?.signedUrl}
async function docAction(id,kind){const d=S.docs.find(x=>x.id===id);if(!d)return;const url=await signedDoc(d);if(!url)return alert('Could not open document.');if(kind==='share'&&navigator.share){try{await navigator.share({title:d.display_name||d.file_name,url})}catch{};return}window.open(url,'_blank')}
async function batchDocs(kind,all=false){const ids=all?S.docs.map(x=>x.id):[...selectedDocs];for(const id of ids){if(kind==='share'){await docAction(id,'share');break}else await docAction(id,'download')}}

async function checkin(){const carrier=main.querySelector('#g-carrier'),payload={carrier_name_snapshot:carrier?.value.trim()||null,carrier_id:carrier?.dataset.entityId||null,driver_name:main.querySelector('#g-driver')?.value.trim()||null,door:main.querySelector('#g-door')?.value.trim()||null,bol_number:main.querySelector('#g-ref')?.value.trim()||null,time_in:S.visit?.time_in||new Date().toISOString()};let error;if(S.visit)({error}=await supabase.from('warehouse_visits').update(payload).eq('id',S.visit.id));else({error}=await supabase.from('warehouse_visits').insert({...payload,organization_id:S.wr.organization_id,warehouse_receipt_id:wrId,direction:'inbound',created_by:await uid()}));if(error)return alert(error.message);manualStep=null;toast('Checked in ✓');await rerender({keepManual:false})}
async function visitUpdate(payload,msg){if(!S.visit)return alert('Check in first.');const{error}=await supabase.from('warehouse_visits').update(payload).eq('id',S.visit.id);if(error)return alert(error.message);manualStep=null;toast(msg+' ✓');await rerender({keepManual:false})}
async function verify(){if(!main.querySelector('#g-verify')?.checked)return alert('Confirm the verification statement.');await visitUpdate({driver_id_verified:true,driver_id_verified_at:new Date().toISOString(),driver_id_verified_by:await uid()},'ID verified')}
async function finishUnload(){await visitUpdate({unload_expected_qty:Number(main.querySelector('#g-exp')?.value||0)||null,unload_actual_qty:Number(main.querySelector('#g-act')?.value||0)||null,unload_uom:main.querySelector('#g-uom')?.value||'PLT',operation_completed_at:new Date().toISOString()},'Unload finished')}
async function saveParties(){const roles=[['customer','g-customer'],['shipper','g-shipper'],['consignee','g-consignee']];for(const[r,id]of roles){const inp=main.querySelector('#'+id),name=inp?.value.trim();if(!name)continue;const e=inp.dataset.entityId?ent(inp.dataset.entityId):S.entities.find(x=>x.name.toLowerCase()===name.toLowerCase());if(r==='customer'){if(e)await supabase.from('jobs').update({customer_id:e.id}).eq('id',S.wr.job_id)}else{await supabase.from('warehouse_receipt_parties').delete().eq('warehouse_receipt_id',wrId).eq('role',r);const{error}=await supabase.from('warehouse_receipt_parties').insert({organization_id:S.wr.organization_id,warehouse_receipt_id:wrId,role:r,entity_id:e?.id||null,display_name:name,phone:e?.phone||null,email:e?.email||null});if(error)return alert(error.message)}}await supabase.from('warehouse_receipts').update({identification_status:'identified'}).eq('id',wrId);manualStep=null;toast('Parties saved ✓');await rerender({keepManual:false})}
async function skipParties(){await supabase.from('warehouse_receipts').update({identification_status:'pending'}).eq('id',wrId);await addEvent('STEP_SKIPPED',{step_key:'parties',reason:'IDENTITY_PENDING'});manualStep=null;toast('Identity pending');await rerender({keepManual:false})}
async function releaseDriver(){if(!S.visit)return alert('Check in first.');if(!window.NodaraWRSignature?.open)return visitUpdate({time_out:new Date().toISOString()},'Driver released');window.NodaraWRSignature.open({onSaved:async()=>{await supabase.from('warehouse_visits').update({time_out:new Date().toISOString()}).eq('id',S.visit.id);manualStep=null;await rerender({keepManual:false})}})}
async function completeWR(){const block=missing().filter(x=>x!=='Driver on site');if(block.length)return alert('Complete the required items first: '+block.join(', '));const{error}=await supabase.from('warehouse_receipts').update({status:'completed',completed_at:new Date().toISOString(),received_at:S.wr.received_at||new Date().toISOString(),processing_status:'completed'}).eq('id',wrId);if(error)return alert(error.message);await addEvent('STEP_COMPLETED',{step_key:'complete'});manualStep=null;await rerender({keepManual:false})}
async function shareWR(){const subj=encodeURIComponent(`${S.wr.receipt_number} · Warehouse Receipt`),body=encodeURIComponent(`Warehouse Receipt ${S.wr.receipt_number}\nCustomer: ${customerName()}\nShipper: ${party('shipper')?.display_name||'—'}\nConsignee: ${party('consignee')?.display_name||'—'}`);location.href=`mailto:?subject=${subj}&body=${body}`}

function bind(){main.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;manualStep=null;render()});main.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;render()});main.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>{manualStep=b.dataset.step;mode='guided';render()});bindSmart();main.querySelector('#cargo-q')?.addEventListener('input',e=>{cargoQuery=e.target.value;clearTimeout(e.target._t);e.target._t=setTimeout(render,180)});main.querySelector('#doc-group')?.addEventListener('change',e=>{docGroup=e.target.value;render()});
 main.querySelectorAll('[data-out]').forEach(b=>b.onclick=async()=>{try{if(b.dataset.out==='pdf')await window.NodaraWROutput?.warehouseReceiptPDF(wrId);if(b.dataset.out==='4x6')await window.NodaraWROutput?.labels4x6(wrId);if(b.dataset.out==='2x1')await window.NodaraWROutput?.labels2x1(wrId)}catch(e){alert(e.message)}});main.querySelectorAll('[data-doc-scan]').forEach(b=>b.onclick=()=>docMetaModal('scan'));main.querySelectorAll('[data-doc-upload]').forEach(b=>b.onclick=()=>docMetaModal('upload'));main.querySelector('#wr21-upload')?.addEventListener('change',uploadFiles);main.querySelectorAll('[data-share]').forEach(b=>b.onclick=shareWR);
 main.querySelector('[data-scan-ref]')?.addEventListener('click',()=>window.nodaraScanTask?.({title:'Scan BOL / PRO / tracking',hint:'Barcode · QR · BOL · PRO · AWB',onScan:async code=>{main.querySelector('#g-ref').value=code;return true}}));main.querySelector('[data-driver-id]')?.addEventListener('click',()=>window.NodaraWRScanner?.open?.({category:'DRIVER_ID',kind:'DRIVER_ID'}));
 main.querySelector('[data-g-checkin]')?.addEventListener('click',checkin);main.querySelector('[data-g-verify]')?.addEventListener('click',verify);main.querySelector('[data-g-start]')?.addEventListener('click',()=>visitUpdate({operation_started_at:new Date().toISOString()},'Unload started'));main.querySelector('[data-g-finish]')?.addEventListener('click',finishUnload);main.querySelector('[data-g-release]')?.addEventListener('click',releaseDriver);main.querySelector('[data-g-parties]')?.addEventListener('click',saveParties);main.querySelector('[data-skip-parties]')?.addEventListener('click',skipParties);main.querySelector('[data-g-complete]')?.addEventListener('click',completeWR);main.querySelector('[data-g-notify]')?.addEventListener('click',async()=>{await addEvent('CUSTOMER_NOTIFIED');manualStep=null;await rerender({keepManual:false})});main.querySelectorAll('[data-skip]').forEach(b=>b.onclick=async()=>{await addEvent('STEP_SKIPPED',{step_key:b.dataset.skip});manualStep=null;await rerender({keepManual:false})});main.querySelectorAll('[data-g-generic]').forEach(b=>b.onclick=async()=>{await addEvent('STEP_COMPLETED',{step_key:b.dataset.gGeneric});manualStep=null;await rerender({keepManual:false})});
 main.querySelectorAll('[data-cargo-add]').forEach(b=>b.onclick=()=>cargoModal());main.querySelectorAll('[data-cargo-edit]').forEach(b=>b.onclick=()=>cargoModal(S.cargo.find(x=>x.id===b.dataset.cargoEdit)));main.querySelectorAll('[data-cargo-inside]').forEach(b=>b.onclick=()=>cargoModal(null,S.cargo.find(x=>x.id===b.dataset.cargoInside)));main.querySelectorAll('[data-cargo-photo]').forEach(b=>b.onclick=()=>window.NodaraWRMedia?.openCargoCamera?.({cargoId:b.dataset.cargoPhoto}));main.querySelectorAll('[data-cargo-control]').forEach(b=>b.onclick=()=>controlModal(b.dataset.cargoControl));main.querySelectorAll('[data-cargo-exception]').forEach(b=>b.onclick=()=>exceptionModal(b.dataset.cargoException));main.querySelectorAll('[data-cargo-label]').forEach(b=>b.onclick=()=>window.NodaraWROutput?.labels4x6(wrId,[b.dataset.cargoLabel]));main.querySelectorAll('[data-cargo-delete]').forEach(b=>b.onclick=()=>{if(confirm('Delete this cargo and nested cargo?'))deleteCargo([b.dataset.cargoDelete])});main.querySelectorAll('[data-cargo-select]').forEach(c=>c.onchange=()=>{c.checked?selectedCargo.add(c.dataset.cargoSelect):selectedCargo.delete(c.dataset.cargoSelect);render()});main.querySelector('[data-cargo-all]')?.addEventListener('change',e=>{selectedCargo.clear();if(e.target.checked)flatCargo().forEach(([x])=>selectedCargo.add(x.id));render()});main.querySelector('[data-cargo-delete-selected]')?.addEventListener('click',()=>{if(selectedCargo.size&&confirm(`Delete ${selectedCargo.size} selected cargo record(s) and nested cargo?`))deleteCargo([...selectedCargo])});
 main.querySelectorAll('[data-putaway]').forEach(b=>b.onclick=()=>putawayModal(b.dataset.putaway));main.querySelector('[data-control-add]')?.addEventListener('click',()=>controlModal());main.querySelector('[data-exception-add]')?.addEventListener('click',()=>exceptionModal());main.querySelectorAll('[data-flag-clear]').forEach(b=>b.onclick=async()=>{await supabase.from('operational_flags').update({active:false,cleared_at:new Date().toISOString(),cleared_by:await uid()}).eq('id',b.dataset.flagClear);await rerender()});
 main.querySelector('[data-edit-parties]')?.addEventListener('click',()=>{mode='guided';manualStep='parties';render()});main.querySelector('[data-edit-arrival]')?.addEventListener('click',()=>{mode='guided';manualStep='check_in';render()});main.querySelector('[data-workflow-edit]')?.addEventListener('click',()=>window.nodaraWorkflowStudio?.('WAREHOUSE_RECEIPT'));
 main.querySelectorAll('[data-doc-preview]').forEach(b=>b.onclick=()=>docAction(b.dataset.docPreview,'preview'));main.querySelectorAll('[data-doc-download]').forEach(b=>b.onclick=()=>docAction(b.dataset.docDownload,'download'));main.querySelectorAll('[data-doc-share]').forEach(b=>b.onclick=()=>docAction(b.dataset.docShare,'share'));main.querySelectorAll('[data-doc-tag]').forEach(b=>b.onclick=()=>docMetaModal('tag',b.dataset.docTag));main.querySelectorAll('[data-doc-select]').forEach(c=>c.onchange=()=>{c.checked?selectedDocs.add(c.dataset.docSelect):selectedDocs.delete(c.dataset.docSelect);render()});main.querySelector('[data-doc-all]')?.addEventListener('change',e=>{selectedDocs.clear();if(e.target.checked)S.docs.forEach(d=>selectedDocs.add(d.id));render()});main.querySelector('[data-doc-download-selected]')?.addEventListener('click',()=>batchDocs('download'));main.querySelector('[data-doc-share-selected]')?.addEventListener('click',()=>batchDocs('share'));main.querySelector('[data-doc-download-all]')?.addEventListener('click',()=>batchDocs('download',true));
 main.querySelector('[data-record-overage]')?.addEventListener('click',async()=>{const s=summary(),delta=s.processed-(s.unloaded||0);const{error}=await supabase.from('operational_flags').insert({organization_id:S.wr.organization_id,warehouse_receipt_id:wrId,flag_type:'OVERAGE',severity:'warning',active:true,source:'SYSTEM_RECONCILIATION',notes:`Processed ${s.processed} vs unloaded ${s.unloaded}; overage ${delta}.`,created_by:await uid()});if(error)return alert(error.message);await rerender()});
}

export async function mountWarehouseReceiptV21(id,{view='guided'}={}){wrId=id;mode=view;tab='overview';manualStep=null;selectedCargo.clear();selectedDocs.clear();await load(id);render();document.body.classList.remove('wr-canonical-loading');main.style.visibility='visible'}
export async function openNewReceivingV21(){document.body.classList.remove('wr21-active','wr19-active');document.querySelector('.wr21-back')?.remove();window.nodaraSetActive?.('wr');main.style.visibility='visible';main.innerHTML=`<section class="wr21-arrival"><div class="wr21-arrivalhero"><div class="wr21-k">WAREHOUSE RECEIVING</div><h1>New receiving</h1><p>Scan first. NODARA creates the provisional WR as soon as you begin capturing the arrival.</p></div><div class="wr21-arrivalgrid"><button class="wr21-arrivalaction" id="nr-code">${scanIcon}<b>Scan code / label</b><small>Barcode · QR · BOL · PRO · AWB · shipping label</small></button><button class="wr21-arrivalaction" id="nr-doc">${docIcon}<b>Scan document</b><small>Capture BOL or paperwork and run document intelligence</small></button></div><div class="wr21-startcard" style="margin-top:10px"><h3>Or start manually</h3><div class="wr21-fields"><label class="wr21-field"><span>Reference type</span><select id="nr-type"><option>BOL</option><option>PRO</option><option>TRACKING</option><option>AWB</option><option>PO</option></select></label><label class="wr21-field"><span>Reference</span><input id="nr-ref" placeholder="Type reference"></label></div><div class="wr21-actions"><button class="primary" id="nr-find">Find expected cargo</button><button id="nr-unidentified">Continue unidentified</button></div></div></section>`;const create=async(ref=null)=>{const type=main.querySelector('#nr-type')?.value||'BOL',value=ref??main.querySelector('#nr-ref')?.value.trim()||null,{data,error}=await supabase.rpc('create_warehouse_receipt_shell_v1',{p_reference_type:type,p_reference_value:value,p_expected_source_type:null,p_expected_source_id:null,p_expected_snapshot:{source:'WR_V21'}});if(error)return alert(error.message);await mountWarehouseReceiptV21(data.warehouse_receipt_id,{view:'guided'});return data.warehouse_receipt_id};main.querySelector('#nr-unidentified').onclick=()=>create();main.querySelector('#nr-find').onclick=async()=>{const ref=main.querySelector('#nr-ref').value.trim();if(!ref)return alert('Scan or enter a reference first.');const{data}=await supabase.from('shipment_references').select('warehouse_receipt_id,reference_value').eq('reference_value',ref).limit(2);if(data?.length===1&&data[0].warehouse_receipt_id)return mountWarehouseReceiptV21(data[0].warehouse_receipt_id,{view:'guided'});await create(ref)};main.querySelector('#nr-code').onclick=()=>window.nodaraScanTask?.({title:'Scan arrival',hint:'Barcode · QR · BOL · PRO · AWB · shipping label',onScan:async code=>{main.querySelector('#nr-ref').value=code;return true}});main.querySelector('#nr-doc').onclick=async()=>{const id=await create();if(id)setTimeout(()=>window.NodaraWRScanner?.open?.({category:'BOL'}),120)}}
window.nodaraOpenCanonicalWRV21=mountWarehouseReceiptV21;
window.nodaraNewCanonicalWRV21=openNewReceivingV21;
